9	 * POST /api/tasks/{taskId}/toggle — tick a task off (or back on). Flips the task's done flag between
10	 * OPEN and DONE, records the transition, and echoes back the saved row. An unknown task is rejected
11	 * with 400 and nothing is written.
12	 */
13	public class ToggleTaskLogic {
14	
15	    public void service(@HttpPathParameter("taskId") String taskId, TaskRepository tasks, Audit audit,
16	            ObjectResponse<TaskView> response) {
17	        Long id = Long.valueOf(taskId);
18	        Task task = tasks.findById(id).orElseThrow(
19	                () -> new HttpException(HttpStatus.BAD_REQUEST, "An existing task is required"));
20	        task.setDone(!task.isDone());
21	        Task saved = tasks.save(task);
22	        audit.record("TASK_TOGGLED id=" + saved.getId() + " done=" + saved.isDone());
23	        response.send(new TaskView(saved.getId(), saved.getProjectId(), saved.getTitle(), saved.isDone()));
24	    }
25	}
